//! Runs programs generated by `reef_infer::codegen` on an Edge TPU and checks
//! them against a host reference (and, where one exists, the compiler).
//!
//!     cargo run --features usb --example codegen_hw [-- target/isa_corpus]

use std::sync::Arc;

use reef_infer::codegen::Quant;
use reef_infer::codegen::elementwise::{self, Requant, SIZE};
use reef_infer::codegen::fc::Fc;
use reef_infer::model::{TfliteModel, load_tflite_model};
use reef_infer::runner::Device;

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u32 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        (self.0 >> 32) as u32
    }
    fn bytes(&mut self, n: usize) -> Vec<u8> {
        (0..n).map(|_| self.next() as u8).collect()
    }
    fn unit(&mut self) -> f32 {
        self.next() as f32 / u32::MAX as f32
    }
}

// xorshift: distinct 8-byte chunks, so layout permutations are visible
fn input() -> Vec<u8> {
    Rng(0x9e3779b97f4a7c15).bytes(SIZE)
}

/// The compiler's FC 64x64 uint8 weights, exported from the CPU model by
/// `tools/isa_corpus/fc_ref.py`.
fn fc_from_json(path: &str) -> Option<Fc> {
    let v: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(path).ok()?).ok()?;
    let f32s = |k: &str| -> Vec<f32> {
        v[k].as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_f64().unwrap() as f32)
            .collect()
    };
    let i64s = |k: &str| -> Vec<i64> {
        v[k].as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_i64().unwrap())
            .collect()
    };
    Some(Fc {
        k: v["k"].as_u64()? as usize,
        n: v["n"].as_u64()? as usize,
        weights: i64s("weights").into_iter().map(|w| w as i8).collect(),
        w_scale: f32s("w_scale"),
        bias: i64s("bias").into_iter().map(|b| b as i32).collect(),
        input: Quant {
            scale: v["in_scale"].as_f64()? as f32,
            zero_point: v["in_zp"].as_i64()? as i32,
        },
        output: Quant {
            scale: v["out_scale"].as_f64()? as f32,
            zero_point: v["out_zp"].as_i64()? as i32,
        },
        relu: false,
    })
}

fn random_fc(rng: &mut Rng, k: usize, n: usize, relu: bool) -> Fc {
    Fc {
        k,
        n,
        weights: (0..n * k).map(|_| rng.next() as i8).collect(),
        w_scale: (0..n).map(|_| 0.002 + 0.01 * rng.unit()).collect(),
        bias: (0..n)
            .map(|_| (rng.next() % 20001) as i32 - 10000)
            .collect(),
        input: Quant {
            scale: 0.02 + 0.02 * rng.unit(),
            zero_point: (rng.next() % 256) as i32,
        },
        output: Quant {
            scale: 0.1 + 0.4 * rng.unit(),
            zero_point: (rng.next() % 256) as i32,
        },
        relu,
    }
}

fn compare_bitstreams(
    what: &str,
    ours: &reef_infer::model::ExecInfo,
    theirs: &reef_infer::model::ExecInfo,
) {
    let (a, b) = (
        &ours.instruction_chunks[0].bitstream,
        &theirs.instruction_chunks[0].bitstream,
    );
    let diff: Vec<usize> = (0..a.len().max(b.len()) / 16)
        .filter(|w| a.get(w * 16..w * 16 + 16) != b.get(w * 16..w * 16 + 16))
        .collect();
    let relocs = |e: &reef_infer::model::ExecInfo| -> Vec<(i32, String)> {
        e.instruction_chunks[0]
            .field_offsets
            .iter()
            .map(|f| (f.offset_bit, format!("{:?}{:?}", f.desc, f.position)))
            .collect()
    };
    println!(
        "{what}: ours {} B, compiler {} B, differing words {diff:?}, relocations equal: {}, parameters equal: {}",
        a.len(),
        b.len(),
        relocs(ours) == relocs(theirs),
        ours.parameters == theirs.parameters
    );
    let (ia, ib) = (
        reef_infer::isa::split(a).unwrap(),
        reef_infer::isa::split(b).unwrap(),
    );
    for (x, y) in ia.iter().zip(&ib) {
        let (dx, dy) = (x.decode().unwrap(), y.decode().unwrap());
        for (f, (va, vb)) in dx
            .layout
            .fields
            .iter()
            .zip(dx.values.iter().zip(&dy.values))
        {
            if va != vb {
                println!(
                    "    {}.{}: ours {va:#x}, compiler {vb:#x}",
                    dx.layout.name, f.name
                );
            }
        }
    }
    if let Some(i) = ours
        .parameters
        .iter()
        .zip(&theirs.parameters)
        .position(|(a, b)| a != b)
    {
        let n = ours
            .parameters
            .iter()
            .zip(&theirs.parameters)
            .filter(|(a, b)| a != b)
            .count();
        println!("    parameters: {n} bytes differ, first at {i}");
    }
}

fn mismatches(got: &[u8], rq: &Requant, x: &[u8]) -> Vec<(u8, u8, u8)> {
    let mut bad: Vec<(u8, u8, u8)> = x
        .iter()
        .zip(got)
        .filter(|&(&x, &g)| rq.apply(x) != g)
        .map(|(&x, &g)| (x, g, rq.apply(x)))
        .collect();
    bad.sort();
    bad.dedup();
    bad
}

async fn run(
    dev: &mut Device,
    model: impl Into<Arc<TfliteModel>>,
    x: &[u8],
) -> Result<Vec<u8>, String> {
    let model = model.into();
    let loaded = dev.load_params(model).await.map_err(|e| e.to_string())?;
    dev.run_inference(&loaded, x.to_vec())
        .await
        .map_err(|e| e.to_string())
}

#[tokio::main]
async fn main() {
    let corpus = std::env::args()
        .nth(1)
        .unwrap_or("target/isa_corpus".into());
    let ref_path =
        format!("{corpus}/act/act_in_range8p0_oprelu_shape16x16x32/model_edgetpu.tflite");

    // ── 1. Bitstream vs compiler.
    let compiled = load_tflite_model(&ref_path).expect("load reference");
    let exe = &compiled.executables[0];
    let q = |l: &reef_infer::model::LayerInfo| Quant {
        scale: l.dequantization_factor,
        zero_point: l.zero_point,
    };
    let (qi, qo) = (q(&exe.input_layers[0]), q(&exe.output_layers[0]));
    let relu = Requant::from_quant(qi, qo, true);
    let ours = elementwise::build(&relu, qi, qo, true).unwrap();
    let (a, b) = (&ours.chunk.bitstream, &exe.instruction_chunks[0].bitstream);
    let diff_words: Vec<usize> = (0..a.len().max(b.len()) / 16)
        .filter(|w| a.get(w * 16..w * 16 + 16) != b.get(w * 16..w * 16 + 16))
        .collect();
    let relocs = |c: &reef_infer::model::ChunkInfo| -> Vec<(i32, String)> {
        c.field_offsets
            .iter()
            .map(|f| (f.offset_bit, format!("{:?}{:?}", f.desc, f.position)))
            .collect()
    };
    println!(
        "relu bitstream: ours {} B, compiler {} B, differing words {:?}, relocations equal: {}",
        a.len(),
        b.len(),
        diff_words,
        relocs(&ours.chunk) == relocs(&exe.instruction_chunks[0])
    );
    println!(
        "output layout equals compiler's: {}",
        format!("{:?}", ours.output.output_layout)
            == format!("{:?}", exe.output_layers[0].output_layout)
    );
    println!(
        "relu requant: {relu:?}  (compiler mult_bits 0x40000005, ours {:#x})",
        relu.mult.to_bits()
    );

    // ── 2. Hardware.
    let mut slot = Some(Device::open().await.expect("open device"));
    let x = input();

    let got_ref = run(slot.as_mut().unwrap(), compiled, &x)
        .await
        .expect("compiler model");
    if let Ok(d) = std::env::var("DUMP") {
        std::fs::write(format!("{d}/x.bin"), &x).unwrap();
        std::fs::write(format!("{d}/y.bin"), &got_ref).unwrap();
    }
    println!(
        "compiler relu on TPU: {} mismatches vs host reference",
        mismatches(&got_ref, &relu, &x).len()
    );

    run_fc(&mut slot, &corpus).await;

    let mut cases: Vec<(&str, Requant, bool)> = vec![("relu (generated)", relu, true)];
    let rq = |in_zp, mult, lo, hi, out_zp| Requant {
        in_zp,
        mult,
        clamp_min: lo,
        clamp_max: hi,
        out_zp,
    };
    cases.extend([
        ("identity", rq(0, 1.0, 0.0, 255.0, 0), true),
        ("x0.5 (ties: half-even?)", rq(0, 0.5, 0.0, 255.0, 0), true),
        ("x0.5 zp 128", rq(128, 0.5, -128.0, 127.0, 128), true),
        ("x-1 zp 128", rq(128, -1.0, -128.0, 127.0, 128), true),
        (
            "x2.5 clamp [-10,40] out_zp 50",
            rq(100, 2.5, -10.0, 40.0, 50),
            true,
        ),
        ("x0.1 in_zp 7", rq(7, 0.1, 0.0, 255.0, 0), true),
        ("x3 in_zp 200 out_zp 3", rq(200, 3.0, -3.0, 252.0, 3), true),
        ("relu, rsv543 cleared (expect hang)", relu, false),
    ]);
    for (name, rq, rsv) in cases {
        let prog = elementwise::build(&rq, qi, qo, rsv).unwrap();
        match run(slot.as_mut().unwrap(), prog.into_model(), &x).await {
            Ok(got) => {
                if let Ok(d) = std::env::var("DUMP") {
                    std::fs::write(format!("{d}/{}.bin", name.split(' ').next().unwrap()), &got)
                        .unwrap();
                }
                let bad = mismatches(&got, &rq, &x);
                let same_as_compiler = got == got_ref;
                println!(
                    "{name:36} {} mismatching values{}{}",
                    bad.len(),
                    if bad.is_empty() {
                        String::new()
                    } else {
                        format!(" e.g. (x, got, want) {:?}", &bad[..bad.len().min(6)])
                    },
                    if same_as_compiler {
                        "  [= compiler output]"
                    } else {
                        ""
                    }
                );
            }
            Err(e) => {
                println!("{name:36} FAILED: {e}");
                reopen(&mut slot).await;
            }
        }
    }
}

/// Reopens the device after a hang (re-runs chip init). The old handle is
/// released first so the interface can be claimed again.
async fn reopen(dev: &mut Option<Device>) {
    *dev = None;
    for _ in 0..20 {
        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
        if let Ok(d) = Device::open().await {
            *dev = Some(d);
            return;
        }
    }
    panic!("device did not come back");
}

async fn run_fc(slot: &mut Option<Device>, corpus: &str) {
    let path =
        format!("{corpus}/fc/fc_K64_N64_actnone_biasTrue_in_range4p0_iouint8/model_edgetpu.tflite");
    let json = std::env::var("FC_REF").unwrap_or(format!("{corpus}/fc_ref.json"));
    let mut rng = Rng(0x2545f4914f6cdd1d);
    if let (Ok(compiled), Some(fc)) = (load_tflite_model(&path), fc_from_json(&json)) {
        let ours = fc.build().unwrap();
        compare_bitstreams("fc exec", &ours.executables[0], &compiled.executables[0]);
        compare_bitstreams("fc caching", &ours.executables[1], &compiled.executables[1]);
        let (mut bad_ref, mut bad_ours, mut same) = (0, 0, true);
        let (compiled, ours) = (Arc::new(compiled), Arc::new(ours));
        for _ in 0..8 {
            let x = rng.bytes(fc.k);
            let want = fc.reference(&x);
            let dev = slot.as_mut().unwrap();
            let r = run(dev, Arc::clone(&compiled), &x).await.unwrap();
            let o = run(dev, Arc::clone(&ours), &x).await.unwrap();
            bad_ref += r.iter().zip(&want).filter(|(a, b)| a != b).count();
            bad_ours += o.iter().zip(&want).filter(|(a, b)| a != b).count();
            same &= r == o;
        }
        println!(
            "fc 64x64 x8 inputs: compiler {bad_ref} / ours {bad_ours} mismatches vs host reference; outputs identical: {same}"
        );
    } else {
        println!("fc: no compiler reference ({path}, {json}); skipping the byte comparison");
    }
    let shapes: Vec<(usize, usize, bool)> = match std::env::var("FC_SHAPES") {
        // e.g. FC_SHAPES=8x64,64x48r  (KxN, r = RELU)
        Ok(v) => v
            .split(',')
            .map(|t| {
                let relu = t.ends_with('r');
                let (k, n) = t.trim_end_matches('r').split_once('x').unwrap();
                (k.parse().unwrap(), n.parse().unwrap(), relu)
            })
            .collect(),
        Err(_) => vec![
            (64, 64, false),
            (64, 64, true),
            (32, 64, false),
            (64, 32, false),
            (16, 16, true),
            (8, 48, false),
            (40, 16, false),
        ],
    };
    for (k, n, relu) in shapes {
        let fc = random_fc(&mut rng, k, n, relu);
        let model = Arc::new(fc.build().unwrap());
        let (mut bad, mut worst, mut ok) = (0, 0i32, true);
        for _ in 0..8 {
            let x = rng.bytes(k);
            let want = fc.reference(&x);
            match run(slot.as_mut().unwrap(), Arc::clone(&model), &x).await {
                Ok(got) => {
                    bad += got.iter().zip(&want).filter(|(a, b)| a != b).count();
                    worst = worst.max(
                        got.iter()
                            .zip(&want)
                            .map(|(&a, &b)| (a as i32 - b as i32).abs())
                            .max()
                            .unwrap_or(0),
                    );
                }
                Err(e) => {
                    println!("fc K={k:2} N={n:2} relu={relu:5}: FAILED {e}");
                    reopen(slot).await;
                    ok = false;
                    break;
                }
            }
        }
        if ok {
            println!(
                "fc K={k:2} N={n:2} relu={relu:5}: {bad}/{} outputs differ from host reference (max |diff| {worst})",
                8 * n
            );
        }
    }
}
